module interleaving_checker (\n    input clk,\n    input rst_n,\n    input start,\n    input [127:0] s1,\n    input [127:0] s2,\n    input [127:0] s,\n    input [4:0] len_s1,\n    input [4:0] len_s2,\n    output reg result,\n    output reg done\n);\n\n    localparam [1:0] IDLE   = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE    = 2'd2;\n    \n    reg [1:0] state;\n    reg [4:0] i;\n    reg [4:0] j;\n    reg dp [0:16][0:16];\n    \n    function [7:0] get_char;\n        input [127:0] vec;\n        input [4:0] idx;\n        get_char = vec[idx*8 +: 8];\n    endfunction\n    \n    wire next_dp = ((i>5'd0 && dp[i-5'd1][j] && get_char(s1, i-5'd1) == get_char(s, i+j-5'd1)) ||\n                    (j>5'd0 && dp[i][j-5'd1] && get_char(s2, j-5'd1) == get_char(s, i+j-5'd1)));\n    \n    integer ii, jj;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            i <= 5'd0;\n            j <= 5'd0;\n            for (ii = 0; ii <= 16; ii = ii + 1) begin\n                for (jj = 0; jj <= 16; jj = jj + 1) begin\n                    dp[ii][jj] <= 1'b0;\n                end\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        dp[0][0] <= 1'b1;\n                        i <= 5'd0;\n                        j <= 5'd0;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if ((i <= len_s1) && (j <= len_s2)) begin\n                        if (!(i == 5'd0 && j == 5'd0)) begin\n                            dp[i][j] <= next_dp;\n                        end\n                    end\n                    \n                    if (j < len_s2) begin\n                        j <= j + 5'd1;\n                    end else begin\n                        j <= 5'd0;\n                        if (i < len_s1) begin\n                            i <= i + 5'd1;\n                        end else begin\n                            result <= dp[len_s1][len_s2];\n                            state <= DONE;\n                        end\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule